/* ============================================
   TOOLTIP COMPONENT
   Contextual text label on hover / focus
   ============================================ */

.ds-tooltip {
  position: relative;
  display: inline-flex;
}

/* ============================================
   PANEL
   ============================================ */

.ds-tooltip__panel {
  position: absolute;
  z-index: 50;
  padding: var(--padding-150) var(--padding-200); /* 6px 8px */
  border-radius: var(--radius-100); /* 4px */
  /* The floating surface, same recipe as Popover: page background (the
     container fill is semi-transparent), hairline border, floating shadow.
     Same-polarity in both themes — light bubble on light, dark on dark —
     softer than the old inverse fill. */
  border: var(--border-025) solid var(--color-bg-container-border);
  background-color: var(--color-bg-page-primary);
  color: var(--color-text-primary);
  box-shadow: var(--shadow-floating);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  white-space: nowrap;
  pointer-events: none;
  /* Hidden panels leave layout entirely: opacity/visibility alone keep the
     box in the page's scrollable overflow, so an edge-adjacent trigger's
     panel adds horizontal scroll while invisible. display transitions
     discretely (allow-discrete holds it through the exit fade; the entry
     fade starts from @starting-style below); browsers without those skip
     the fades but show and hide correctly. */
  display: none;
  opacity: 0;
  transition-property: opacity, transform, display;
  transition-duration: var(--motion-duration-fast);
  transition-timing-function: var(--motion-ease-standard);
  transition-behavior: allow-discrete;
}

.ds-tooltip__panel--visible {
  display: block;
  opacity: 1;
}

/* ============================================
   POSITIONS
   ============================================ */

.ds-tooltip__panel--top {
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  margin-bottom: var(--gap-100); /* 4px */
}

.ds-tooltip__panel--top.ds-tooltip__panel--visible {
  transform: translateX(-50%) translateY(0);
}

.ds-tooltip__panel--bottom {
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  margin-top: var(--gap-100);
}

.ds-tooltip__panel--bottom.ds-tooltip__panel--visible {
  transform: translateX(-50%) translateY(0);
}

.ds-tooltip__panel--left {
  right: 100%;
  top: 50%;
  transform: translateY(-50%) translateX(4px);
  margin-right: var(--gap-100);
}

.ds-tooltip__panel--left.ds-tooltip__panel--visible {
  transform: translateY(-50%) translateX(0);
}

.ds-tooltip__panel--right {
  left: 100%;
  top: 50%;
  transform: translateY(-50%) translateX(-4px);
  margin-left: var(--gap-100);
}

.ds-tooltip__panel--right.ds-tooltip__panel--visible {
  transform: translateY(-50%) translateX(0);
}

/* Entry states for the display flip: a panel arriving from display:none has
   no prior computed style, so these supply the fade's starting frame. Each
   mirrors its position's hidden transform above. */
@starting-style {
  .ds-tooltip__panel--top.ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateX(-50%) translateY(4px);
  }

  .ds-tooltip__panel--bottom.ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateX(-50%) translateY(-4px);
  }

  .ds-tooltip__panel--left.ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateY(-50%) translateX(4px);
  }

  .ds-tooltip__panel--right.ds-tooltip__panel--visible {
    opacity: 0;
    transform: translateY(-50%) translateX(-4px);
  }
}

/* ============================================
   ARROW
   ============================================ */

/* The arrow is a rotated square in the panel's fill. It overlaps the panel
   by a pixel more than before so its opaque fill covers the panel border
   behind it, and draws the hairline itself on its two outward edges only. */
.ds-tooltip__arrow {
  position: absolute;
  width: 8px;
  height: 8px;
  background-color: var(--color-bg-page-primary);
  transform: rotate(45deg);
}

/* Arrow — top position (arrow points down) */
.ds-tooltip__panel--top .ds-tooltip__arrow {
  bottom: -5px;
  left: 50%;
  margin-left: -4px;
  border-right: var(--border-025) solid var(--color-bg-container-border);
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
}

/* Arrow — bottom position (arrow points up) */
.ds-tooltip__panel--bottom .ds-tooltip__arrow {
  top: -5px;
  left: 50%;
  margin-left: -4px;
  border-top: var(--border-025) solid var(--color-bg-container-border);
  border-left: var(--border-025) solid var(--color-bg-container-border);
}

/* Arrow — left position (arrow points right) */
.ds-tooltip__panel--left .ds-tooltip__arrow {
  right: -5px;
  top: 50%;
  margin-top: -4px;
  border-top: var(--border-025) solid var(--color-bg-container-border);
  border-right: var(--border-025) solid var(--color-bg-container-border);
}

/* Arrow — right position (arrow points left) */
.ds-tooltip__panel--right .ds-tooltip__arrow {
  left: -5px;
  top: 50%;
  margin-top: -4px;
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
  border-left: var(--border-025) solid var(--color-bg-container-border);
}

'use client';

import {
  useState,
  useEffect,
  useRef,
  useId,
  cloneElement,
  isValidElement,
  type ReactNode,
  type ReactElement,
} from 'react';
import './Tooltip.css';
import { MOTION_HOVER_SHOW_DELAY_MS, MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';

export interface TooltipProps {
  /** Trigger element */
  children?: ReactNode;
  /** Tooltip text content */
  content: string;
  /** Preferred position */
  position?: 'top' | 'bottom' | 'left' | 'right';
  /** Delay before showing (in ms) */
  showDelay?: number;
  /** Delay before hiding (in ms) */
  hideDelay?: number;
  /** Additional CSS classes */
  className?: string;
}

/**
 * Tooltip component for contextual text labels.
 * Appears on hover or focus with a short delay.
 * Rides the system's floating surface — page background, hairline border,
 * floating shadow — so the bubble stays light in light theme and dark in dark.
 */
export const Tooltip = ({
  children,
  content,
  position = 'top',
  showDelay = MOTION_HOVER_SHOW_DELAY_MS,
  hideDelay = MOTION_HOVER_HIDE_DELAY_MS,
  className = '',
}: TooltipProps) => {
  const [visible, setVisible] = useState(false);
  const showTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const hideTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const tooltipId = useId();

  const baseClass = 'ds-tooltip';

  const show = () => {
    clearTimeout(hideTimeoutRef.current);
    showTimeoutRef.current = setTimeout(() => setVisible(true), showDelay);
  };

  const hide = () => {
    clearTimeout(showTimeoutRef.current);
    hideTimeoutRef.current = setTimeout(() => setVisible(false), hideDelay);
  };

  useEffect(() => {
    return () => {
      clearTimeout(showTimeoutRef.current);
      clearTimeout(hideTimeoutRef.current);
    };
  }, []);

  // Escape dismisses the tooltip while it is visible (WCAG 1.4.13). A
  // document listener rather than a wrapper handler, so it also works when
  // the tooltip was triggered by hover and focus is elsewhere.
  useEffect(() => {
    if (!visible) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        clearTimeout(showTimeoutRef.current);
        clearTimeout(hideTimeoutRef.current);
        setVisible(false);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [visible]);

  // Associate the trigger with the tooltip for screen readers. When the
  // child is a single element, put aria-describedby directly on it.
  const trigger = isValidElement(children)
    ? cloneElement(children as ReactElement<{ 'aria-describedby'?: string }>, {
        'aria-describedby': tooltipId,
      })
    : children;

  const containerClasses = [baseClass, className].filter(Boolean).join(' ');
  const panelClasses = [
    `${baseClass}__panel`,
    `${baseClass}__panel--${position}`,
    visible ? `${baseClass}__panel--visible` : '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <span
      className={containerClasses}
      onMouseEnter={show}
      onMouseLeave={hide}
      onFocus={show}
      onBlur={hide}
    >
      {trigger}

      {/*
        No aria-hidden toggle: the trigger's aria-describedby points here, and
        show is delayed, so the description must be computable the moment
        focus lands. The panel hides with display:none (accessible-name
        computation includes hidden nodes referenced by IDREF, so the
        description survives), which keeps an edge-adjacent panel out of the
        page's scrollable overflow while hidden.
      */}
      <span className={panelClasses} role="tooltip" id={tooltipId}>
        {content}
        <span className={`${baseClass}__arrow`} />
      </span>
    </span>
  );
};
